namespace ghidra.app.plugin.core.symboltree.nodes;







using docking.widgets.tree;
using generic.theme;
using ghidra.app.plugin.core.symboltree;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.task;

public class LabelCategoryNode : SymbolCategoryNode {

	public static readonly Icon OPEN_FOLDER_LABELS_ICON =
		new GIcon("icon.plugin.symboltree.node.category.label.open");
	public static readonly Icon CLOSED_FOLDER_LABELS_ICON =
		new GIcon("icon.plugin.symboltree.node.category.label.closed");

	public LabelCategoryNode(Program program) : base(SymbolCategory.LABEL_CATEGORY, program)
    {
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return expanded ? OPEN_FOLDER_LABELS_ICON : CLOSED_FOLDER_LABELS_ICON;
	}

	/* @Override */
	public string getToolTip() {
		return "Symbols for Global Labels";
	}

	/* @Override */
	public bool supportsDataFlavors(DataFlavor[] dataFlavors) {
		foreach (DataFlavor flavor in dataFlavors) {
			if (flavor == CodeSymbolNode.LOCAL_DATA_FLAVOR) {
				return true;
			}
		}
		return false;
	}

	/* @Override */
	protected bool supportsSymbol(Symbol symbol) {
		if (!symbol.isGlobal() || symbol.isExternal()) {
			return false;
		}
		SymbolType symbolType = symbol.getSymbolType();
		return symbolType == symbolCategory.getSymbolType();
	}

	/* @Override */
	protected List<GTreeNode> getSymbols(SymbolType type, TaskMonitor monitor)
    {
		return getSymbols(type, true, monitor);
	}

	/* @Override */
	public bool canPaste(List<GTreeNode> pastedNodes) {
		foreach (GTreeNode treeNode in pastedNodes) {
			if (!(treeNode is LabelCategoryNode)) {
				return false;
			}
		}

		return true;
	}

	/* @Override */
	public Comparator<GTreeNode> getChildrenComparator() {
		// this category node uses OrganizationNodes
		return OrganizationNode.COMPARATOR;
	}

	/* @Override */
	public SymbolNode symbolAdded(Symbol symbol, TaskMonitor monitor) {
		if (!isLoaded()) {
			return null;
		}

		// only include global symbols
		if (!symbol.isGlobal()) {
			return null;
		}

		if (!supportsSymbol(symbol)) {
			return null;
		}

		SymbolNode newNode = SymbolNode.createNode(symbol, program);
		doAddNode(this, newNode);
		return newNode;
	}
}
